"""Remove all attributes from the output"""
def remove_result_attr(result: Any) -> object {
    filtered_list = [];
    for tup in result {
        lis = `list(tup);
        removeset = `set([2]);
        filtered_list.append(
            `tuple(
                [
                    v
                    for (i, v) in enumerate(lis)
                    if (i not in removeset)
                ]
            )
        );
    }
    return filtered_list;
}
